int main(void)
{
    unsigned int sum;
    unsigned int len;
    unsigned int i;

    sum = 0u;
    len = 0u;
    i = 0u;
    while (blob[i] != 0) {
        sum = (sum * 31u + (unsigned int)(unsigned char)blob[i]) & 0xFFFFu;
        len = len + 1u;
        i = i + 1u;
    }
    printf("blob len=%u sum=%u\n", len, sum);
    return 0;
}
